//! melee_fighter::tu::ftmaterial vs the C (gen/cref/tu/ftmaterial_ops.c: the whole TU, shipping contraction, recording stubs, three random
//! fighters). Generated by gen/mtu/mkdriver.py from gen/mtu/specs/ftmaterial.json; regenerate the C side with
//! `bash rust/melee_fighter/gen/mtu/regen_ftmaterial.sh`.
#![allow(static_mut_refs, non_snake_case, non_upper_case_globals, unused_variables, unused_parens, unused_unsafe, unused_mut, unused_imports, clippy::all)]
