const NG: usize = 3;
const NJ: usize = 8;
const NP: usize = 16;
static mut GO: *mut [HSD_GObj; NG] = null_mut();
static mut JO: *mut [HSD_JObj; NJ] = null_mut();
static mut FT: *mut [Fighter; NG] = null_mut();
static mut FDATA: *mut [ftData; NG] = null_mut();
static mut PARTS: *mut [[FighterBone; 64]; NG] = null_mut();
static mut CD: *mut ftCommonData = null_mut();
static mut PLINKV: [*mut HSD_GObj; 16] = [null_mut(); 16];
static mut PADB: *mut [[u8; 2048]; 96] = null_mut();

fn pick_HSD_GObj() -> *mut HSD_GObj { let r = rnd(); unsafe { if r % 6 == 0 { null_mut() } else { &raw mut (*GO)[((r >> 8) as usize) % NG] } } }
fn pick_HSD_JObj() -> *mut HSD_JObj { let r = rnd(); unsafe { if r % 6 == 0 { null_mut() } else { &raw mut (*JO)[((r >> 8) as usize) % NJ] } } }
fn pick_Fighter() -> *mut Fighter { let r = rnd(); unsafe { if r % 6 == 0 { null_mut() } else { &raw mut (*FT)[((r >> 8) as usize) % NG] } } }
fn pick_Item() -> *mut Item { null_mut() }
fn pick_HSD_DObj() -> *mut HSD_DObj { null_mut() }
pub unsafe extern "C" fn cbev1(g: *mut HSD_GObj) { t(7001); t(pi(g)); }
pub unsafe extern "C" fn cbev2(g: *mut HSD_GObj) { t(7002); t(pi(g)); }
pub unsafe extern "C" fn cbp1(g: *mut HSD_GObj) -> i32 { t(7003); t(pi(g)); (fv() & 1) as i32 }
pub unsafe extern "C" fn cbp2(g: *mut HSD_GObj) -> i32 { t(7004); t(pi(g)); (fv() & 1) as i32 }
pub unsafe extern "C" fn cbev3(g: *mut HSD_GObj, hh: *mut HSD_GObj) { t(7005); t(pi(g)); t(pi(hh)); }
fn pick_fn(kind: i32) -> usize {
    let r = rnd();
    if r & 3 == 0 { return 0; }
    match kind {
        1 => if r & 4 != 0 { cbev1 as usize } else { cbev2 as usize },
        2 => if r & 4 != 0 { cbp1 as usize } else { cbp2 as usize },
        3 => cbev3 as usize,
        _ => 0,
    }
}

fn bz<T>() -> *mut T { Box::leak(Box::new(unsafe { core::mem::zeroed::<T>() })) }
static mut MO: *mut [HSD_MObj; 3] = null_mut();
static mut MAT: *mut [HSD_Material; 3] = null_mut();
static mut TOBJ: *mut [HSD_TObj; 3] = null_mut();
static mut SHAD: *mut HSD_TObj = null_mut();
static mut TOON: *mut HSD_TObj = null_mut();
static mut PE: *mut [HSD_PEDesc; 3] = null_mut();
static mut MINFO: *mut HSD_MObjInfo = null_mut();
static mut TXP: *mut [HSD_TExp; 2] = null_mut();
static mut IMGD: *mut HSD_ImageDesc = null_mut();
static mut REGD: bool = false;
unsafe extern "C" fn cbst(m: *mut HSD_MObj, tb: *mut HSD_TObj, r: u32) { t(7100); t(pi(m)); t(pi(tb)); t(r); }

unsafe fn install_hooks() {
    MO = bz(); MAT = bz(); TOBJ = bz(); SHAD = bz(); TOON = bz(); PE = bz(); MINFO = bz(); TXP = bz(); IMGD = bz();
    m::ext::hook::HSD_TExpSetReg = Some(|a0| unsafe {
        let mut c = a0 as *mut HSD_TECnst;
        let mut n = 0;
        t(1500);
        while !c.is_null() && n < 4 {
            n += 1;
            let v = (*c).val as *const u8;
            t((*c).r#type as u32); t((*c).reg as u32); t((*c).comp as u32); t((*c).ctype as u32); t((*c).idx as u32); t(pi(v));
            if !v.is_null() && pi(v) == 0xFFFF_FFFF {
                t(*v as u32);
                if (*c).comp as u32 == HSD_TE_RGB as u32 { t(*v.add(1) as u32); t(*v.add(2) as u32); t(*v.add(3) as u32); }
            }
            c = (*c).next as *mut HSD_TECnst;
        }
    });
    m::ext::hook::HSD_SetupTevStage = Some(|a0| unsafe {
        let d = &*(a0 as *const HSD_TevDesc);
        t(1501); t(d.flags as u32); t(d.stage as u32); t(d.coord as u32); t(d.map as u32); t(d.color as u32);
        t(d.u.tevconf.clr_op as u32); t(d.u.tevconf.clr_a as u32); t(d.u.tevconf.clr_b as u32); t(d.u.tevconf.clr_c as u32); t(d.u.tevconf.clr_d as u32);
        t(d.u.tevconf.alpha_a as u32); t(d.u.tevconf.alpha_b as u32); t(d.u.tevconf.alpha_c as u32); t(d.u.tevconf.alpha_d as u32);
        t(d.u.tevconf.kcsel as u32); t(d.u.tevconf.kasel as u32);
    });
    m::ext::hook::HSD_SetupRenderModeWithCustomPE = Some(|rm, pe| unsafe {
        t(1502); t(rm); t(pi(pe as *const u8));
        if !pe.is_null() {
            let pe = &*(pe as *const HSD_PEDesc);
            t(pe.flags as u32); t(pe.r#type as u32); t(pe.src_factor as u32); t(pe.dst_factor as u32); t(pe.logic_op as u32); t(pe.z_comp as u32);
            t(pe.alpha_comp0 as u32); t(pe.ref0 as u32); t(pe.alpha_op as u32); t(pe.alpha_comp1 as u32); t(pe.ref1 as u32); t(pe.dst_alpha as u32);
        }
    });
}

unsafe fn world() {
    *GO = core::mem::zeroed();
    *JO = core::mem::zeroed();
    *FT = core::mem::zeroed();
    *FDATA = core::mem::zeroed();
    *CD = core::mem::zeroed();
    for i in 0..NG { fill_Fighter(&mut (*FT)[i]); }
    for i in 0..NJ { fill_HSD_JObj(&mut (*JO)[i]); }
    for i in 0..NG { fill_HSD_GObj(&mut (*GO)[i]); }
    for i in 0..NG {
        (*GO)[i].user_data = &raw mut (*FT)[i] as *mut c_void;
        (*GO)[i].hsd_obj = &raw mut (*JO)[i] as *mut c_void;
        (*GO)[i].classifier = HSD_GOBJ_CLASS_FIGHTER as _;
        (*GO)[i].next = if i + 1 < NG { &raw mut (*GO)[i + 1] } else { null_mut() };
        (*FT)[i].gobj = &raw mut (*GO)[i];
        (*FT)[i].ft_data = &raw mut (*FDATA)[i];
        (*FT)[i].grab_cb = Some(cbev1); (*FT)[i].grabbed_cb = Some(cbev3);
        (*FT)[i].kind = ((*FT)[i].kind as u32 % 27) as _; (*FT)[i].player_id %= 4; (*FT)[i].x618_player_id %= 4;
        for b in 0..64 { if b < NP { fill_FighterBone(&mut (*PARTS)[i][b]); } else { (*PARTS)[i][b] = core::mem::zeroed(); (*PARTS)[i][b].anon_8.anon_0.set_flags_b1(1); } (*PARTS)[i][b].joint = &raw mut (*JO)[(i * 5 + b * 3) % NJ]; }
        (*FT)[i].parts = (*PARTS)[i].as_mut_ptr();
// the ftData pointer words: one pad block each (the C driver's order)
        { let mut pk = i * 24; macro_rules! nx { () => {{ pk += 1; (*PADB)[pk - 1].as_mut_ptr() as *mut _ }}; }
          let d = &mut (*FDATA)[i];
          d.x0 = nx!(); d.ext_attr = nx!(); d.x8 = nx!(); d.xC = nx!(); d.x10 = nx!(); d.x14 = nx!(); d.x18 = nx!(); d.x1C = nx!();
          d.x20 = nx!(); d.x24 = nx!(); d.x28 = nx!(); d.x2C = nx!(); d.x30 = nx!(); d.x34 = nx!(); d.x38 = nx!(); d.x3C = nx!();
          d.x40 = nx!(); d.x44 = nx!(); d.x48_items = nx!(); d.x4C_sfx = nx!(); d.x50 = nx!(); d.x54 = nx!(); d.x58 = nx!(); d.x5C = nx!(); }
    }
    for i in 0..NJ {
        (*JO)[i].parent = if i != 0 { &raw mut (*JO)[(i - 1) / 2] } else { null_mut() };
        (*JO)[i].child = if 2 * i + 1 < NJ { &raw mut (*JO)[2 * i + 1] } else { null_mut() };
        (*JO)[i].next = if (i & 1) != 0 && i + 1 < NJ { &raw mut (*JO)[i + 1] } else { null_mut() };
    }
    h::P_FT_COMMON_DATA = CD;
    for i in 0..16 { PLINKV[i] = null_mut(); }
    PLINKV[HSD_GOBJ_PLINK_FIGHTER as usize] = &raw mut (*GO)[0];
    h::PLINK_HEAD = Some(|link| PLINKV[link as usize]);
    for i in 0..NG { (*FT)[i].x61A_controller_index %= 6; }
    {
        if !REGD { REGD = true; preg(MO, size_of_val(&*MO)); preg(TOBJ, size_of_val(&*TOBJ)); preg(SHAD, size_of_val(&*SHAD)); preg(TOON, size_of_val(&*TOON)); preg(PE, size_of_val(&*PE)); preg(MAT, size_of_val(&*MAT)); preg(TXP, size_of_val(&*TXP)); }
        *MO = core::mem::zeroed(); *MAT = core::mem::zeroed(); *TOBJ = core::mem::zeroed(); *SHAD = core::mem::zeroed(); *TOON = core::mem::zeroed(); *PE = core::mem::zeroed();
        *MINFO = core::mem::zeroed(); *TXP = core::mem::zeroed(); *IMGD = core::mem::zeroed();
        (*MINFO).setup_tev = Some(cbst);
        for q in 0..3usize {
            (*MO)[q].parent.class_info = MINFO.cast();
            (*MO)[q].rendermode = rnd();
            (*MO)[q].mat = &raw mut (*MAT)[q];
            (*MAT)[q].ambient.r = fv() as u8; (*MAT)[q].ambient.g = fv() as u8; (*MAT)[q].ambient.b = fv() as u8; (*MAT)[q].ambient.a = fv() as u8;
            (*MAT)[q].diffuse.r = fv() as u8; (*MAT)[q].diffuse.g = fv() as u8; (*MAT)[q].diffuse.b = fv() as u8; (*MAT)[q].diffuse.a = fv() as u8;
            (*MAT)[q].specular.r = fv() as u8; (*MAT)[q].specular.g = fv() as u8; (*MAT)[q].specular.b = fv() as u8; (*MAT)[q].specular.a = fv() as u8;
            (*MAT)[q].alpha = rg(); (*MAT)[q].shininess = rg();
            (*MO)[q].tobj = if fv() & 1 != 0 { &raw mut (*TOBJ)[q] } else { null_mut() };
            (*TOBJ)[q].next = if q < 2 && (fv() & 1) != 0 { &raw mut (*TOBJ)[q + 1] } else { null_mut() };
            (*MO)[q].pe = &raw mut (*PE)[q];
            (*PE)[q].flags = fv() as _; (*PE)[q].ref0 = fv() as _;
        }
        melee_runtime::tu::mobj::native::tobj_shadows = if fv() & 1 != 0 { SHAD } else { null_mut() };
        melee_runtime::tu::mobj::native::tobj_toon = if fv() & 1 != 0 { TOON } else { null_mut() };
        (*TOON).imagedesc = if fv() & 1 != 0 { IMGD } else { null_mut() };
        (*TOON).next = null_mut(); (*SHAD).next = null_mut();
        melee_fighter::tu::ftco_800c7ca0::ft_804D6580 = &raw mut (*MO)[1]; melee_fighter::tu::ft_0c8c::ft_804D6588 = &raw mut (*MO)[2];
        (*TXP)[0].cnst.reg = fv() as u8; (*TXP)[0].cnst.r#type = HSD_TE_CNST; (*TXP)[0].cnst.comp = (fv() & 7) as _;
        { let cp = (&raw mut (*CD).x6D8) as *mut u8; for q in 0..24usize { *cp.add(q) = fv() as u8; } }
    }
}
unsafe fn hworld() {
    for i in 0..NG { hash_Fighter(&(*FT)[i]); }
    for i in 0..NJ { hash_HSD_JObj(&(*JO)[i]); }
    for i in 0..NG { hash_HSD_GObj(&(*GO)[i]); }
    for i in 0..NG { for b in 0..NP { hash_FighterBone(&(*PARTS)[i][b]); } }
    for q in 0..3usize { hm(pi((*TOBJ)[q].next as *const u8)); } hm(pi((*SHAD).next as *const u8)); hm(pi((*TOON).next as *const u8));
}

#[test]
fn ftmaterial_matches_c() {
    unsafe {
        GO = bz(); JO = bz(); FT = bz(); FDATA = bz(); PARTS = bz(); CD = bz(); PADB = bz();
        preg(GO, core::mem::size_of_val(&*GO));
        preg(JO, core::mem::size_of_val(&*JO));
        preg(FT, core::mem::size_of_val(&*FT));
        preg(FDATA, core::mem::size_of_val(&*FDATA));
        preg(PADB, core::mem::size_of_val(&*PADB));
        freg(cbev1 as usize); freg(cbev2 as usize); freg(cbp1 as usize); freg(cbp2 as usize); freg(cbev3 as usize);
        ftmaterial_stubs::install();
        install_hooks();
    }
    let mut c = Check::new(include_str!("data/tu_ftmaterial_ops.txt"));
    const NOPS: u32 = 4;
    for op in 0..NOPS {
        for k in 0..600u32 {
            case(op, k);
            if std::env::var("TUV").is_ok() { eprintln!("op {op} k {k}"); }
            let mut ret = 0u32;
            let res = std::panic::catch_unwind(core::panic::AssertUnwindSafe(|| unsafe {
                world();
                let gi = (rnd() as usize) % NG;
                let g = &raw mut (*GO)[gi];
                let fp = &raw mut (*FT)[gi];
                match op {
                    0 => { { m::ftMaterial_800BF260(); hm(m::ftMObj.setup.is_some() as u32); } }
                    1 => { { let mo_ = &raw mut (*MO)[(fv() as usize) % 3]; let rm_ = rnd(); let un_ = fv(); melee_runtime::tu::pobj::ext::HSD_GObj_804D7814 = g; m::ftMaterial_800BF2B8(mo_, rm_, un_); } }
                    2 => { { let mo_ = &raw mut (*MO)[(fv() as usize) % 3]; let rm_ = rnd(); let mut tx_: HSD_TExp = core::mem::zeroed(); let r_ = m::ftMaterial_800BF534(fp, mo_, &mut tx_, rm_); ret = (!r_.is_null()) as u32; hm(tx_.cnst.reg as u32); hm(tx_.cnst.comp as u32); hm(tx_.cnst.idx as u32); hm(pi(tx_.cnst.val as *const u8)); hm(tx_.cnst.r#type as u32); } }
                    3 => { { let mo_ = &raw mut (*MO)[(fv() as usize) % 3]; let tp_ = if fv() & 1 != 0 { &raw mut (*TXP)[0] } else { null_mut() }; m::ftMaterial_800BF6BC(fp, mo_, tp_); } }
                    _ => unreachable!(),
                }
                hworld();
            }));
            if res.is_err() { c.assert_line(op, k); continue; }
            unsafe { c.line(op, k, ret); }
        }
    }
    assert_eq!(c.done(), NOPS * 600);
}
